begin;
create extension if not exists pgtap with schema extensions;
set local search_path=extensions,public;
select no_plan();
\ir fixtures/storefront.fixture.inc
select ok(not private.is_synthetic_test_location('f2000000-0000-0000-0000-000000000001','f3000000-0000-0000-0000-000000000001'),'empty environment grants nothing');
select ok(not has_function_privilege('service_role','private.configure_synthetic_test_location(text,uuid,uuid,timestamptz,text)','EXECUTE'),'service role cannot configure synthetic scope');
select ok(not has_table_privilege('authenticated','private.synthetic_test_locations','SELECT'),'browser cannot read scope configuration');
select ok(not has_table_privilege('service_role','private.synthetic_test_environment','INSERT'),'service role cannot declare preview environment');
insert into private.synthetic_test_environment(project_ref,expires_at) values('aaaaaaaaaaaaaaaaaaaa',now()+interval '6 days');
update public.restaurants set slug='test-synthetic-a',display_name='TEST Synthetic A' where id='f2000000-0000-0000-0000-000000000001';
update public.locations set slug='test-synthetic-a-mitte',display_name='TEST Synthetic Mitte' where id='f3000000-0000-0000-0000-000000000001';
select throws_ok($q$select private.configure_synthetic_test_location('bbbbbbbbbbbbbbbbbbbb','f2000000-0000-0000-0000-000000000001','f3000000-0000-0000-0000-000000000001',now()+interval '1 day','Synthetic scope test')$q$,'P0001','Explicit preview environment configuration required','wrong environment rejected');
select lives_ok($q$select private.configure_synthetic_test_location('aaaaaaaaaaaaaaaaaaaa','f2000000-0000-0000-0000-000000000001','f3000000-0000-0000-0000-000000000001',now()+interval '1 day','Synthetic scope test')$q$,'operator can configure synthetic scope');
select ok(private.is_synthetic_test_location('f2000000-0000-0000-0000-000000000001','f3000000-0000-0000-0000-000000000001'),'scope is active');
select ok(private.is_location_ordering_enabled('f2000000-0000-0000-0000-000000000001','f3000000-0000-0000-0000-000000000001'),'ordering gate accepts synthetic scope');
select ok(not private.is_location_go_live('f2000000-0000-0000-0000-000000000001','f3000000-0000-0000-0000-000000000001'),'production gate remains closed');
select ok(not private.is_location_ordering_enabled('f2000000-0000-0000-0000-000000000002','f3000000-0000-0000-0000-000000000001'),'cross tenant scope denied');
insert into public.restaurant_feature_flags(restaurant_id,feature_key,enabled) values('f2000000-0000-0000-0000-000000000001','payment.online',true),('f2000000-0000-0000-0000-000000000001','fulfillment.delivery',true) on conflict(restaurant_id,feature_key) do update set enabled=true;
select ok(not private.is_location_feature_enabled('f2000000-0000-0000-0000-000000000001','f3000000-0000-0000-0000-000000000001','payment.online'),'online payments unavailable');
select ok(not private.is_location_feature_enabled('f2000000-0000-0000-0000-000000000001','f3000000-0000-0000-0000-000000000001','fulfillment.delivery'),'delivery unavailable');
select is((select go_live_status from public.restaurant_activation_states where restaurant_id='f2000000-0000-0000-0000-000000000001'),'blocked','production approval not fabricated');
select ok(exists(select 1 from private.provide_admin_audit where restaurant_id='f2000000-0000-0000-0000-000000000001' and action='synthetic_test_locations.insert' and actor_user_id is null),'operator action audited without impersonation');
update public.locations set status='suspended' where id='f3000000-0000-0000-0000-000000000001';
select ok(not private.is_location_ordering_enabled('f2000000-0000-0000-0000-000000000001','f3000000-0000-0000-0000-000000000001'),'suspension closes preview');
update public.locations set status='active' where id='f3000000-0000-0000-0000-000000000001';
update private.synthetic_test_locations set created_at=now()-interval '2 days',expires_at=now()-interval '1 day';
select ok(not private.is_location_ordering_enabled('f2000000-0000-0000-0000-000000000001','f3000000-0000-0000-0000-000000000001'),'expiry closes preview');
select * from finish();
rollback;
